    accent-color: #667eea;
    flex-shrink: 0;
    margin-top: 4px;
}

label {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    font-size: 16px;
    color: #1a1a1a;
    line-height: 1.5;
    cursor: pointer;
}

label a {
    color: #667eea;
    text-decoration: underline;
    text-decoration-color: rgba(102, 126, 234, 0.4);
}

label a:hover {
    color: #764ba2;
    text-decoration-color: rgba(118, 75, 162, 0.6);
}

label a:focus {
    outline: 2px solid #667eea;
    outline-offset: 2px;
    border-radius: 2px;
}

.required {
    color: #d32f2f;
    font-weight: 600;
}

.helper-text {
    font-size: 14px;
    color: #999;
    line-height: 1.5;
    margin-left: 32px;
}

.error-text {
    font-size: 14px;
    color: #d32f2f;
    line-height: 1.5;
    margin-left: 32px;
    font-weight: 500;
}

.submit-btn {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
    border: none;
    padding: 12px 24px;
    font-size: 16px;
    font-weight: 600;
    border-radius: 8px;
    cursor: pointer;
    transition: transform 0.2s, box-shadow 0.2s;
    margin-top: 8px;
}

.submit-btn:hover:not(:disabled) {
    transform: translateY(-2px);
    box-shadow: 0 8px 20px rgba(102, 126, 234, 0.4);
}

.submit-btn:active:not(:disabled) {
    transform: translateY(0);
}

.submit-btn:focus {
    outline: 2px solid #667eea;
    outline-offset: 2px;
}

.submit-btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

