            id: v.id,
            impact: v.impact,
            description: v.description,
            targets: v.nodes.map(n => n.target)
        })),
        bp: bp.map(v => ({
            id: v.id,
            description: v.description,
            targets: v.nodes.map(n => n.target)
        }))
    };

    console.log(JSON.stringify(report, null, 2));
    process.exit(wcag.length > 0 ? 1 : 0);
})().catch(err => {
    console.error('Test error:', err.message);
    process.exit(2);
});

